import{z as n,x as s,o as t,c as d,q as i,j as B,D as e,d as r,s as A,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"激光直写与封装光刻","description":"","frontmatter":{"title":"激光直写与封装光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/laser-direct-write-packaging.md","filePath":"litho/laser-direct-write-packaging.md","lastUpdated":1791413859000}'),p={name:"litho/laser-direct-write-packaging.md"};function D(h,a,m,u,C,f){const l=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="激光直写与封装光刻" tabindex="-1">激光直写与封装光刻 <a class="header-anchor" href="#激光直写与封装光刻" aria-label="Permalink to &quot;激光直写与封装光刻&quot;">​</a></h1><div class="epigraph"><p>封装的线宽在微米，场在厘米；激光直写或大视场投影够用，不必借 EUV 的随机与掩模链。</p><footer>—— 对照 LDI（laser direct imaging）与先进封装光刻尺度的通称</footer></div><p><a href="/litho/xray-near-field">上一课</a>关掉接近式短波主路。缺口是后段互连与封装的尺度。本课钉激光直写与封装光刻。面板级更大场，留给<a href="/litho/panel-level-litho">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先进封装 RDL、铜柱、部分 fan-out，特征比 BEOL 松、面积比芯片大。工具：激光直写（无掩模或用 DMD）、或大视场步进投影。套刻与畸变来自翘曲的重建晶圆或有机基板，不是高 NA 镜头。用前道光刻规则去卡封装，会过度工程；用封装工具去印 MMP，会不够。</p><p>缺口是<strong>尺度换工具族</strong>，不是分辨率竞赛。主干不把封装并进逻辑 EUV 附录——本课显式分开。</p><p><span class="marginnote">数字实例：逻辑关键层的图形在几十纳米量级、单场约 26 mm × 33 mm；封装 RDL 的线宽/线隙常在 2–10 μm，面板级单次曝光场可到几十厘米见方。像素数差了好几个数量级——这就是「直写在封装可行、在逻辑不可行」的算术根。</span></p><h3 id="无掩模在封装为何可行" tabindex="-1">无掩模在封装为何可行 <a class="header-anchor" href="#无掩模在封装为何可行" aria-label="Permalink to &quot;无掩模在封装为何可行&quot;">​</a></h3><p>面积仍大，但像素比逻辑少几个数量级（微米 vs 纳米），直写 wph 可以接受。与晶圆多束电子的面积墙对照：光子封装直写的「像素负担」轻。</p><p><span class="marginnote">翘曲补偿、自动对焦行程、厚胶是封装光刻的一等规格，NILS 不是。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选工具：按最小线宽、场、基板、产能。计量：不同套刻标记与红外/透过方案（键合课将遇）。与逻辑接口：凸点节距仍在收紧，封装光刻也在进步，但路径是大视场低 NA，不是 High-NA。</p>',12)),(t(),B(o,null,{default:e(()=>[A(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E5%B0%81%E8%A3%85%E5%B1%82%E5%9B%BE%E5%BD%A2%E9%9C%80%E6%B1%82%22%5D%20--%3E%20FIELD%7B%22%E5%8D%95%E6%AC%A1%E8%A6%81%E7%9B%96%E5%A4%9A%E5%A4%A7%E5%9C%BA%EF%BC%9F%22%7D%0A%20%20FIELD%20--%3E%7C%22%E5%8E%98%E7%B1%B3%E5%88%B0%E5%87%A0%E5%8D%81%E5%8E%98%E7%B1%B3%22%7C%20LDI%5B%22LDI%20%E6%BF%80%E5%85%89%E7%9B%B4%E5%86%99%22%5D%0A%20%20FIELD%20--%3E%7C%22%E4%B8%AD%E7%AD%89%E5%9C%BA%E3%80%81%E8%BF%BD%E6%B1%82%E4%BA%A7%E8%83%BD%22%7C%20STEP%5B%22%E5%A4%A7%E8%A7%86%E5%9C%BA%E6%AD%A5%E8%BF%9B%E6%8A%95%E5%BD%B1%22%5D%0A%20%20LDI%20--%3E%20NOMASK%5B%22%E5%85%8D%E6%8E%A9%E6%A8%A1%E7%89%88%EF%BC%8C%E6%8D%A2%E7%89%88%E5%8D%B3%E6%94%B9%E5%9B%BE%22%5D%0A%20%20STEP%20--%3E%20RETICLE%5B%22%E9%9C%80%E6%8E%A9%E6%A8%A1%E7%89%88%EF%BC%8C%E6%89%B9%E9%87%8F%E6%91%8A%E8%96%84%E6%88%90%E6%9C%AC%22%5D%0A%20%20NOMASK%20--%3E%20WARP%5B%22%E9%83%BD%E5%90%83%E7%BF%98%E6%9B%B2%E8%A1%A5%E5%81%BF%E4%B8%8E%E5%AF%B9%E7%84%A6%E8%A1%8C%E7%A8%8B%22%5D%0A%20%20RETICLE%20--%3E%20WARP%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"分辨率需求低，DOF 需求高（厚胶、形貌）。低 NA 大视场光学或扫描激光满足这组，而不是高 NA。信息量按微米栅格，数据路径像 PCB LDI。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：DOF（焦深）就是「晶圆面上下晃多少还能印清楚」。厚胶要求整层胶均匀曝光，等于逼着工具要大 DOF；而 DOF 大致随 \\(\\mathrm{NA}^2\\) 反比缩小——所以封装光学选低 NA 不只是为了省钱，是厚胶逼的。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为封装光刻是「过时的逻辑光刻」。它的难点换了维度：重建晶圆翘曲几十微米、有机基板吸潮变形、厚胶深宽比——这些问题在逻辑前道的教科书里几乎不出现，却决定封装良率。")],-1)),(t(),B(o,null,{default:e(()=>[A(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20UM%5B%22%E5%BE%AE%E7%B1%B3%E7%89%B9%E5%BE%81%22%5D%20--%3E%20PKG%5B%22LDI%20%2F%20%E5%A4%A7%E8%A7%86%E5%9C%BA%E6%8A%95%E5%BD%B1%22%5D%0A%20%20NM%5B%22%E7%BA%B3%E7%B1%B3%20MMP%22%5D%20--%3E%20FEOL%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%20EUV%2F%E6%B5%B8%E6%B2%A1%22%5D%0A%20%20PKG%20--%3E%20WARP%5B%22%E7%BF%98%E6%9B%B2%20%2F%20%E5%8E%9A%E8%83%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有 fan-out 当同一工具。不给凸点节距路线当常数。本课不覆盖显示（后课）。</p><p>后课默认：封装用大视场低 NA 或 LDI；下一课面板比圆片更大时的畸变与套刻。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>封装光刻尺度在微米与大场，工具是 LDI 或低 NA 大视场。</li><li>直写因像素粗而可行，与晶圆电子束直写不是同一墙。</li><li>翘曲与厚胶是主规格。</li><li>出处：LDI 与先进封装光刻通称。</li></ul>',5))])}const P=n(p,[["render",D]]);export{F as __pageData,P as default};
